mapper.select:
SELECT 
  FROM agent_daily_metric m
 WHERE m.tenant_code = #{tenantCode}
   AND m.stat_date >= #{from}
   AND m.stat_date <= #{to}

   AND m.agent_id = #{agentId}

 GROUP BY COALESCE(m.agent_id, 0)
 ORDER BY ${orderBy} DESC NULLS LAST, agent_id
 LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT COALESCE(m.agent_id, 0))
  FROM agent_daily_metric m
 WHERE m.tenant_code = #{tenantCode}
   AND m.stat_date >= #{from}
   AND m.stat_date <= #{to}

   AND m.agent_id = #{agentId}
